from pathlib import Path
import json,zipfile,hashlib,xml.etree.ElementTree as E,re,subprocess
ROOT=Path(__file__).resolve().parents[3];R=ROOT/'planning/utkala-odisha/checkouts/utkal-fieldwork-pack';O=Path(__file__).resolve().parent
# Independent read of ZIP/XML, no workbook writes and no atlas extractor invocation.
f=R/'kb/research/references/census-2011/c16-odisha.xlsx';N={'x':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
with zipfile.ZipFile(f)as z:
 strings=[''.join(t.itertext())for t in E.fromstring(z.read('xl/sharedStrings.xml')).findall('x:si',N)]
 sheet=E.fromstring(z.read('xl/worksheets/sheet1.xml'))
 rows=[];geos={}
 for rr in sheet.findall('x:sheetData/x:row',N):
  v={}
  for c in rr.findall('x:c',N):
   val=c.find('x:v',N)
   if val is not None:v[re.sub(r'\d','',c.attrib['r'])]=strings[int(val.text)]if c.get('t')=='s'else val.text
  if v.get('A')!='C0116' or str(v.get('C')).zfill(3)!='388':continue
  geos[v['D']]=v['E']
  if v['D']!='00000':continue
  rows.append({'row':int(rr.attrib['r']),'state_code':v['B'],'district_code':v['C'],'subdistrict_code':v['D'],'area_name':v['E'],'code':str(v['F']).zfill(6),'raw_label':v['G'],'values':[int(v[x])for x in 'HIJKLMNOP']})
a=json.loads((R/'kb/research/voices/population-2011.json').read_text());d=a['areas']['388'];errors=[]
assert set(x['code']for x in rows)==set(d['rows'])
for x in rows:
 t=d['rows'][x['code']];v=x['values'];p,m,w,r,rm,rw,u,um,uw=v
 if t['values']!=v or t['source_row']!=x['row']:errors.append(['parity',x['code']])
 if not(p==m+w and r==rm+rw and u==um+uw and p==r+u and m==rm+um and w==rw+uw):errors.append(['sums',x['code']])
groups=[x for x in rows if x['code'].endswith('000')];children=[x for x in rows if not x['code'].endswith('000')];residual=[]
for g in groups:
 kids=[x for x in children if x['code'][:3]==g['code'][:3]]
 if kids:
  if [sum(x['values'][i]for x in kids)for i in range(9)]!=g['values']:errors.append(['children',g['code']])
 else:residual.append(g)
sums=[sum(x['values'][i]for x in groups)for i in range(9)];assert sums==d['population'];assert not errors
r={'source':a['sources']['c16'],'actual_workbook_sha256':hashlib.sha256(f.read_bytes()).hexdigest(),'district':d['name'],'code':'388','row_range':[min(x['row']for x in rows),max(x['row']for x in rows)],'row_count':len(rows),'group_count':len(groups),'subordinate_count':len(children),'numeric_cells_compared':len(rows)*9,'all_identifiers_numeric_cells_and_locators_match':True,'errors':errors,'population_H_to_P':d['population'],'group_sums_H_to_P':sums,'residual_groups_without_children':residual,'other_geographies_not_combined':{k:v for k,v in geos.items()if k!='00000'},'original_rows':rows,'selected_profiles':{k:d['rows'][v['code']]['values'][0]for k,v in a['profiles'].items()if v['code']in d['rows']},'odia_group_vs_return':{c:d['rows'][c]for c in ['015000','015043']}}
assert r['actual_workbook_sha256']==r['source']['sha256'];(O/'source-parity.json').write_text(json.dumps(r,ensure_ascii=False,indent=2)+'\n');print(json.dumps({k:v for k,v in r.items()if k in ['row_count','group_count','subordinate_count','numeric_cells_compared','row_range','population_H_to_P','odia_group_vs_return','other_geographies_not_combined']},ensure_ascii=False))

