import pathlib,json,hashlib,zipfile,xml.etree.ElementTree as E,subprocess,re
from html.parser import HTMLParser
O=pathlib.Path(__file__).resolve().parent;R=O.parents[2];repo=R/'planning/utkala-odisha/checkouts/utkal-fieldwork-pack'
def rd(p):return json.loads(p.read_text())
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def wr(p,d):p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
atlas=rd(repo/'kb/research/voices/population-2011.json');a=atlas['areas']['388'];src=repo/'kb/research/references/census-2011/c16-odisha.xlsx';assert sha(src)==atlas['sources']['c16']['sha256'];ns={'m':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
with zipfile.ZipFile(src) as z:
 strings=[''.join(e.itertext()) for e in E.fromstring(z.read('xl/sharedStrings.xml')).findall('m:si',ns)];sheet=E.fromstring(z.read('xl/worksheets/sheet1.xml'))
rows=[]
for row in sheet.findall('.//m:row',ns):
 v={}
 for c in row:
  n=c.find('m:v',ns)
  if n is not None:v[re.sub(r'\d','',c.attrib['r'])]=strings[int(n.text)] if c.attrib.get('t')=='s' else n.text
 if v.get('C')=='388' and v.get('D')=='00000':rows.append({'row':int(row.attrib['r']),'code':v['F'],'label':v['G'],'values':[int(float(v[k])) for k in 'HIJKLMNOP']})
assert {r['code'] for r in rows}==set(a['rows'])
for r in rows:
 q=a['rows'][r['code']];assert q['source_row']==r['row'] and q['values']==r['values'];v=r['values'];assert all(v[k]==v[k+1]+v[k+2] for k in [0,3,6]);assert all(v[k]==v[k+3]+v[k+6] for k in range(3))
groups=[r for r in rows if atlas['labels'][r['code']]['level']=='language_group'];assert [sum(r['values'][i] for r in groups) for i in range(9)]==a['population']
children_checks=[]
for g in groups:
 c=[r for r in rows if atlas['labels'][r['code']].get('parent')==g['code']]
 if c:assert [sum(r['values'][i] for r in c) for i in range(9)]==g['values'];children_checks.append(g['code'])
wr(O/'original-row-parity.json',{'source_sha256':sha(src),'filter':'Sheet1 district C388/subdistrict D00000; H:P numeric cells','rows':rows,'numeric_cells':len(rows)*9,'all_numeric_and_row_anchors_equal':True,'row_code_sets_complete':True,'sex_and_residence_sums_pass':True,'parent_groups_population_pass':True,'parent_member_groups_checked':children_checks})
connections=[c for c in rd(repo/'kb/research/voices/district-connections.json')['connections'] if c['district']=='388'];links=[l for l in rd(repo/'kb/research/related-discoveries.json')['links'] if l['from']=='/languages/districts/ganjam/']
class Extract(HTMLParser):
 def __init__(self):super().__init__();self.on=False;self.depth=0;self.text=[];self.links=[]
 def handle_starttag(self,t,attrs):
  if t=='article':self.on=True
  if self.on:
   if t=='a':self.links.extend(v for k,v in attrs if k=='href')
   if t in ['p','h1','h2','h3','tr','section','summary']:self.text.append('\n')
 def handle_endtag(self,t):
  if t=='article':self.on=False
 def handle_data(self,d):
  if self.on:self.text.append(d)
html=repo/'projects/site/dist-publish/languages/districts/ganjam/index.html';parser=Extract();parser.feed(html.read_text());text='\n'.join(' '.join(l.split()) for l in ''.join(parser.text).splitlines() if l.strip());(O/'cached-article.txt').write_text(text+'\n')
assert not connections and not links

wr(O/'render-summary.json',{'path':str(html.relative_to(repo)),'sha256':sha(html),'article_links':parser.links,'text_sha256':sha(O/'cached-article.txt'),'connections':connections,'related':links,'district':a,'source':atlas['sources']['c16']})
print(len(rows),len(groups),len(rows)*9,a['population'])

