from pathlib import Path
from html.parser import HTMLParser
from urllib.parse import urlparse,parse_qs
import json,re
O=Path(__file__).resolve().parent;R=O.parents[2]/'planning/utkala-odisha/checkouts/utkal-fieldwork-pack';d=json.loads((R/'kb/research/voices/population-2011.json').read_text());a=d['areas']['388']
class P(HTMLParser):
 def __init__(self):super().__init__();self.rows=[];self.row=None;self.cell=None
 def handle_starttag(self,t,ats):
  if t=='tr':self.row={'cells':[]}
  if self.row is not None:
   if t in ['td','th']:self.cell=[]
   if t=='a':
    h=dict(ats).get('href','')
    if '/languages/atlas/?' in h:self.row['query']=parse_qs(urlparse(h).query)
 def handle_data(self,s):
  if self.cell is not None:self.cell.append(s)
 def handle_endtag(self,t):
  if t in ['td','th'] and self.cell is not None:self.row['cells'].append(''.join(self.cell));self.cell=None
  if t=='tr' and self.row is not None:self.rows.append(self.row);self.row=None
p=P();p.feed((R/'projects/site/dist-publish/languages/districts/ganjam/index.html').read_text());checks=[]
for row in p.rows:
 if 'query' not in row:continue
 q=row['query'];code=q['language'][0];res=q['residence'][0];i={'total':0,'rural':3,'urban':6}[res];v=a['rows'][code]['values'];cells=row['cells'];assert int(cells[1].replace(',',''))==v[i]
 if len(cells)==5:assert int(cells[2].replace(',',''))==v[i+1] and int(cells[3].replace(',',''))==v[i+2]
 share=v[i]/a['population'][i]*100;want='<0.01%' if 0<share<.01 else f'{share:.2f}%';assert cells[-1]==want
 checks.append({'code':code,'residence':res,'persons':v[i],'share':want,'cells_checked':len(cells)-1})
expected=sum(v['values'][i]>0 for v in a['rows'].values() for i in [0,3,6]);assert len(checks)==expected
(O/'rendered-row-parity.json').write_text(json.dumps({'result':'PASS','rows':len(checks),'numeric_share_cells':sum(x['cells_checked'] for x in checks),'checks':checks},indent=2)+'\n');print(len(checks),sum(x['cells_checked'] for x in checks))
